INSERT INTO social_posts (
  account_id,
  platform,
  external_post_id,
  text,
  post_url,
  content_type,
  publish_time,
  like_count,
  comment_count,
  raw_json
) VALUES 
  {{ $('Scrape facebook posts').item.json.posts.map(item => {
    const escapeSql = (val) => {
      if (val === null || val === undefined) return 'NULL';
      if (typeof val === 'number' || typeof val === 'boolean') return val;
      // Escape single quotes for SQL strings
      return `'${String(val).replace(/'/g, "''")}'`;
    };

    // Logic to determine content type based on the data provided
    let contentType = 'text';
    if (item.images && item.images.length > 1) {
      contentType = 'carousel';
    } else if (item.images && item.images.length === 1) {
      contentType = 'image';
    } else if (item.videoDetails && Object.keys(item.videoDetails).length > 0) {
      contentType = 'video';
    }

    // --- IMPORTANT: ACCOUNT_ID LOGIC ---
    // You must replace 'null' below with the actual Internal ID 
    // from your 'social_accounts' table that corresponds to item.author.id
    const dbAccountId = $('Upsert facebook Account').item.json.id; 

    // Store the ENTIRE item object (images, comments, author, etc.) as a JSON string
    const otherData = JSON.stringify({
        "image": item.image,
        "images": item.images,
        "author": item.author,
        "video_details": item.videoDetails,
        "video_view_count": item.videoViewCount
    });

    return `(
      ${dbAccountId},
      'facebook',
      ${escapeSql(item.id)},
      ${escapeSql(item.text)},
      ${escapeSql(item.url)},
      '${contentType}',
      '${new Date(item.publishTime * 1000).toISOString()}',
      ${item.reactionCount},
      ${item.commentCount},
      ${escapeSql(otherData)} 
    )`;
  }).join(",") }}
ON CONFLICT (platform, external_post_id) 
DO UPDATE SET
  text = EXCLUDED.text,
  like_count = EXCLUDED.like_count,
  comment_count = EXCLUDED.comment_count,
  view_count = EXCLUDED.view_count,
  raw_json = EXCLUDED.raw_json,
  updated_at = NOW();

INSERT INTO social_post_metrics (
  external_post_id,  
  like_count, 
  comment_count
) VALUES 
  {{ $('Scrape facebook posts').item.json.posts.map(item => {
  let sql = `('${item.id}', ${item.reactionCount}, ${item.commentCount})`;
  return sql;
  }).join(",") }}
